    if (ph.mode === "respond" && idx === ph.responder) { wantKillYudo = true; preferKill = true; }
    else if (ph.mode === "relay" && idx === ph.responder) { wantKillYudo = true; preferKill = true; }
    else if (ph.mode === "relay" && idx === ph.problemIssuer) { wantKillYudo = false; preferKill = false; }
