    if (active.length === 0) return { end: true, winner: null, note: multi ? "전원 탈락 · 무승부" : "솔로 탈락" };
    if (multi && active.length === 1) return { end: true, winner: active[0], note: "최후 1인" };
    if (!multi && !survived) return { end: true, winner: null, note: "솔로 탈락" };
    if (!multi && survived && turnNo >= gm.maxRounds) return { end: true, winner: active[0], note: "솔로 클리어" };
    if (multi && turnNo >= gm.maxRounds) return { end: true, winner: active[0], note: "T" + gm.maxRounds + " 종료 · 생존 " + active.join(", ") };
