    gm.resolving = true;
    var ch = gm.challenge;
    var player = geonmatErrorCurrentPlayer(game);
    var subE = player ? gm.submissions[player] : null;
    var valE = subE ? subE.value : null;
    var tol = ch.tolerance || ch.stepN || dictMiniStepOrDefault(game.gueruleSettings);
    var errE = valE == null ? 1 : geonmatRelativeError(valE, ch.targetCount);
    var errPctE = geonmatErrorPercent(errE);
