      if ((m = s.match(/^두음\s+\S+/i))) { tokens.push(m[0]); s = s.substring(m[0].length).trim(); continue; }
      if ((m = s.match(/^첫수\s+\S+/i))) { tokens.push(m[0]); s = s.substring(m[0].length).trim(); continue; }
      if ((m = s.match(/^인원\s+\d+/i))) { tokens.push(m[0]); s = s.substring(m[0].length).trim(); continue; }
      if ((m = s.match(/^라운드\s*\d+/i))) { tokens.push(m[0]); s = s.substring(m[0].length).trim(); continue; }
